    reg [7:0] ram [0:7];
    reg [2:0] addr;
    reg [7:0] data;
    wire [7:0] q;
    reg [7:0] qs [0:7];
    integer i;
    always @(posedge clk) begin
        if (enable) begin
            for (i = 7; i > 0; i = i - 1) ram[i] <= ram[i-1];
            ram[0] <= S;
